-- Signature: app.activity_feed(p_site_id uuid, p_actor_id uuid, p_actor_type text, p_action text, p_from timestamp with time zone, p_until timestamp with time zone, p_before_time timestamp with time zone, p_before_id bigint, p_limit integer)
-- Owner: cms_migration_owner
